import random

def generate(rng, n):
    if n <= 1:
        return [1, []]
    edges = []
    for i in range(1, n):
        parent = rng.randint(0, i - 1)
        edges.append([parent, i])
    return [n, edges]

def generate_worst(rng, n):
    if n <= 1:
        return [1, []]
    edges = [[i, i + 1] for i in range(n - 1)]
    return [n, edges]

